// Validate that we received the expected fields
var body = msg.payload;
if (!body || !body.patient_id) {
    node.warn('Missing patient_id in ThingSpeak update payload');
    return null;
}

// Build a clean message for downstream nodes
msg.patient_id = body.patient_id;
msg.entry_id   = body.entry_id;
msg.sent_at    = body.sent_at;
msg.channel_id = body.thingspeak_channel_id;

// Sensor values (may be undefined if not present in the reading)
msg.heart_rate               = body.heart_rate;
msg.body_temperature         = body.body_temperature;
msg.blood_pressure_systolic  = body.blood_pressure_systolic;
msg.blood_pressure_diastolic = body.blood_pressure_diastolic;
msg.rolling_mean_hr          = body.rolling_mean_hr;
msg.z_score_hr               = body.z_score_hr;
msg.anomalies                = body.anomalies || [];

// Convenience: build the public ThingSpeak chart URL
if (msg.channel_id) {
    msg.chart_url = 'https://thingspeak.com/channels/' + msg.channel_id + '/charts/1';
}

// Tag with received timestamp
msg.received_at = new Date().toISOString();

return msg;

// Send to alert branch if anomalies are present, always forward to dashboard
var hasAnomalies = msg.anomalies && msg.anomalies.length > 0;

if (hasAnomalies) {
    // Output 1: normal dashboard update
    // Output 2: alert branch
    return [msg, msg];
}
return [msg, null];

// Build a human-readable summary for the debug / dashboard panel
var p = msg.patient_id;
var lines = [
    '=== Patient: ' + p + ' ===',
    'Entry ID   : ' + msg.entry_id,
    'Sent at    : ' + msg.sent_at,
];

if (msg.heart_rate !== undefined)
    lines.push('HR         : ' + msg.heart_rate + ' bpm');
if (msg.body_temperature !== undefined)
    lines.push('Temp       : ' + msg.body_temperature + ' °C');
if (msg.blood_pressure_systolic !== undefined)
    lines.push('BP         : ' + msg.blood_pressure_systolic + '/' + msg.blood_pressure_diastolic + ' mmHg');
if (msg.rolling_mean_hr !== undefined)
    lines.push('Mean HR    : ' + msg.rolling_mean_hr + ' (15 min)');
if (msg.z_score_hr !== undefined)
    lines.push('Z-score HR : ' + msg.z_score_hr);
if (msg.chart_url)
    lines.push('Chart      : ' + msg.chart_url);

msg.payload = lines.join('\n');
return msg;

var lines = ['⚠️  ALERT — Patient: ' + msg.patient_id];
msg.anomalies.forEach(function(a) {
    lines.push('  Metric: ' + a.metric + '  |  z-score: ' + a.z_score + '  |  Severity: ' + (a.severity || 'unknown'));
});
lines.push('  HR: ' + (msg.heart_rate || 'N/A') + ' bpm');
lines.push('  Time: ' + msg.sent_at);
msg.payload = lines.join('\n');
msg.topic   = 'alert';
return msg;

// Keep a rolling list of the last 20 alerts in flow context
var alerts = flow.get('alert_history') || [];
alerts.unshift({
    patient_id: msg.patient_id,
    anomalies:  msg.anomalies,
    sent_at:    msg.sent_at,
    heart_rate: msg.heart_rate
});
if (alerts.length > 20) alerts.pop();
flow.set('alert_history', alerts);

msg.payload = alerts;
return msg;

var patient_id = msg.payload.patient_id;
if (!patient_id) {
    node.warn('No patient_id provided for flush');
    return null;
}
msg.method  = 'POST';
msg.url     = 'http://thingspeak_forwarder:5004/patients/' + patient_id + '/flush';
msg.payload = {};
return msg;

var result = msg.payload;
if (result && result.flushed) {
    msg.payload = '✅ Flush OK — patient: ' + result.patient_id;
} else {
    msg.payload = '⚠️  Flush failed — ' + (result && result.reason ? result.reason : 'unknown error');
}
return msg;

var s = msg.payload;
if (!s || !s.counters) {
    msg.payload = 'Could not reach ThingSpeak Forwarder';
    return msg;
}
var lines = [
    '--- ThingSpeak Forwarder Status ---',
    'Sent   : ' + s.counters.sent,
    'Errors : ' + s.counters.errors,
    'Dropped: ' + s.counters.dropped,
    'Queue  : ' + s.queue_depth + ' patient(s) pending',
];
if (s.pending_patients && s.pending_patients.length) {
    lines.push('Pending: ' + s.pending_patients.join(', '));
}
Object.keys(s.last_sent || {}).forEach(function(pid) {
    lines.push('Last sent [' + pid + ']: ' + s.last_sent[pid]);
});
msg.payload = lines.join('\n');
return msg;
